/** Only known UI templates; captured numbers and currency are never converted. */
export function canonicalCopyHindi(text: string): string | undefined {
  let m: RegExpMatchArray | null
  if ((m = text.match(/^(\d+) of (\d+) projects$/))) return `${m[1]} / ${m[2]} प्रोजेक्ट`
  if ((m = text.match(/^(\d+) projects · unlimited$/))) return `${m[1]} प्रोजेक्ट · असीमित`
  if ((m = text.match(/^(\d+) Shorts made$/))) return `${m[1]} Shorts बनाए गए`
  if ((m = text.match(/^(\d+) of your first 4 Shorts$/))) return `आपके पहले 4 Shorts में से ${m[1]}`
  if ((m = text.match(/^Generate · (\d+) cr →$/))) return `बनाएँ · ${m[1]} cr →`
  if ((m = text.match(/^Need (\d+) more credits$/))) return `${m[1]} और क्रेडिट चाहिए`
  if ((m = text.match(/^Trim ([\d,]+) characters to continue$/))) return `जारी रखने के लिए ${m[1]} अक्षर कम करें`
  if ((m = text.match(/^(\d+) credits \/ video$/))) return `${m[1]} क्रेडिट / वीडियो`
  if ((m = text.match(/^≈ (\d+) finished films? — (\d+) AI scenes$/))) return `≈ ${m[1]} तैयार वीडियो — ${m[2]} AI दृश्य`
  if ((m = text.match(/^Exporting (\d+)% — keep this tab visible$/))) return `निर्यात ${m[1]}% — यह टैब खुला और दिखाई देता रखें`
  if ((m = text.match(/^Kineo lists and charges plan prices in (USD) worldwide\. Your bank may convert the charge to your local currency and may add conversion or cross-border fees\.$/))) return `Kineo दुनिया भर में प्लान की कीमतें ${m[1]} में दिखाता और वसूलता है। आपका बैंक राशि को स्थानीय मुद्रा में बदल सकता है और मुद्रा परिवर्तन या अंतरराष्ट्रीय लेनदेन शुल्क ले सकता है।`
  return undefined
}
